import { TASK, TAKEOFF, GATES, PAD, random, trialParameters, SPLITS } from './tasks/drone-hard/task.mjs';
import { initialState, validateSource } from './tasks/drone-hard/sim.mjs';

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const norm = (v) => Math.hypot(v.x, v.y, v.z);
const copy = (v) => ({ ...v });
