        const bodyZ = -Math.sin(mAtt.roll);
        const dirX = Math.cos(mAtt.yaw) * bodyX + Math.sin(mAtt.yaw) * bodyZ;
        const dirY = Math.cos(mAtt.pitch) * Math.cos(mAtt.roll);
        const dirZ = -Math.sin(mAtt.yaw) * bodyX + Math.cos(mAtt.yaw) * bodyZ;

