        desPitch = clamp(desPitch, -0.14, 0.14);
        desRoll = clamp(desRoll, -0.14, 0.14);
      }

      // 4. Invert inner attitude loop with torque bias
      // The simulator already applies 65*(cmd - att) - 13.4*rate + 22*int + bias.
      // That has natural frequency sqrt(65) = 8.06 rad/s and damping 13.4/(2*8.06) = 0.83.
      // If we want slightly faster response (e.g. kp=80, kd=16) and exact cancellation of int and bias:
      const desAlphaRoll = 80 * (desRoll - att.roll) - 16.0 * rates.roll;
      const desAlphaPitch = 80 * (desPitch - att.pitch) - 16.0 * rates.pitch;

      const cmdRoll = clamp(att.roll + (desAlphaRoll + 13.4 * rates.roll - 22 * intRoll - biasRoll) / 65, -0.6, 0.6);
      const cmdPitch = clamp(att.pitch + (desAlphaPitch + 13.4 * rates.pitch - 22 * intPitch - biasPitch) / 65, -0.6, 0.6);

      const desYawRate = -3.0 * att.yaw;
      const desAlphaYaw = 8.0 * (desYawRate - rates.yaw);
      const cmdYawRate = clamp(rates.yaw + (desAlphaYaw + 0.4 * rates.yaw - biasYaw) / 8, -2, 2);

      const cosTilt = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      const cmdThrust = clamp((totalAccY * thrustScale) / cosTilt, 0.05, 0.96);

      prevAction = { thrust: cmdThrust, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };
      return prevAction;
    },
  };
}
