      const overlapsFrame = dy <= outer + TASK.bodyHeight && dz <= outer + TASK.bodyRadius && !fits;
      if (overlapsFrame) state.reason = 'gate frame collision';
      if (i === state.gateIndex && old.x < x && state.pos.x >= x && fits) state.gateIndex++;
    }
  }
  const error = Math.hypot(state.pos.x - PAD.centre.x, state.pos.z - PAD.centre.z);
  if (state.gateIndex === GATES.length && error <= TASK.landingRadius && state.pos.y <= TASK.bodyHeight + 0.025 &&
      norm(state.vel) < TASK.landingSpeed && Math.max(Math.abs(att.roll), Math.abs(att.pitch)) < TASK.landingTilt) state.landedFor += dt;
  else state.landedFor = 0;
  if (state.landedFor >= TASK.landingHold && !state.reason) state.reason = 'landed';
}

async function main() {
  const path = process.argv[2] || '/workspace/controller.js';
  validateSource(path);
  const mod = await import(path + '?t=' + Date.now());
  const makeController = mod.default;

  let smokePassed = 0, totalPassed = 0;
  const reasons = {};

  for (const seed of SPLITS.smoke) {
    const parameters = trialParameters(seed), state = initialState(parameters), rng = random((seed ^ 0xa5a5a5a5) >>> 0);
    const ctrl = makeController();
    for (let step = 0; step < Math.round(TASK.duration / TASK.dt) && !state.reason; step++) {
      const rawAction = ctrl.step(observation(state, rng));
      const action = {
        thrust: clamp(rawAction.thrust, 0, 1),
        roll: clamp(rawAction.roll, -0.6, 0.6),
        pitch: clamp(rawAction.pitch, -0.6, 0.6),
        yawRate: clamp(rawAction.yawRate, -2, 2),
      };
      for (let sub = 0; sub < TASK.substeps && !state.reason; sub++) integrate(state, action, parameters, TASK.dt / TASK.substeps);
    }
    const reason = state.reason || 'time limit';
    const success = reason === 'landed';
    if (success) smokePassed++;
    console.log(`SMOKE ${seed}: ${success ? 'PASS' : 'FAIL'} (${reason}) gates=${state.gateIndex}/3 t=${state.t.toFixed(2)} pos=(${state.pos.x.toFixed(2)},${state.pos.y.toFixed(2)},${state.pos.z.toFixed(2)}) att=(${state.att.roll.toFixed(2)},${state.att.pitch.toFixed(2)})`);
  }

  for (let seed = 1; seed <= 200; seed++) {
    const parameters = trialParameters(seed), state = initialState(parameters), rng = random((seed ^ 0xa5a5a5a5) >>> 0);
    const ctrl = makeController();
    for (let step = 0; step < Math.round(TASK.duration / TASK.dt) && !state.reason; step++) {
      const rawAction = ctrl.step(observation(state, rng));
      const action = {
        thrust: clamp(rawAction.thrust, 0, 1),
        roll: clamp(rawAction.roll, -0.6, 0.6),
        pitch: clamp(rawAction.pitch, -0.6, 0.6),
        yawRate: clamp(rawAction.yawRate, -2, 2),
      };
      for (let sub = 0; sub < TASK.substeps && !state.reason; sub++) integrate(state, action, parameters, TASK.dt / TASK.substeps);
    }
    const reason = state.reason || 'time limit';
    const success = reason === 'landed';
    if (success) totalPassed++;
    else {
      reasons[reason] = (reasons[reason] || 0) + 1;
      if (Object.values(reasons).reduce((a,b)=>a+b,0) <= 15) {
        console.log(`  Fail seed ${seed}: ${reason} gates=${state.gateIndex}/3 t=${state.t.toFixed(2)} pos=(${state.pos.x.toFixed(2)},${state.pos.y.toFixed(2)},${state.pos.z.toFixed(2)}) att=(${state.att.roll.toFixed(2)},${state.att.pitch.toFixed(2)})`);
      }
    }
  }
  console.log(`\nSmoke: ${smokePassed}/4 | Seeds 1..200: ${totalPassed}/200 | Fail reasons:`, reasons);
}
main();
