          if (dx > 0.05 && (abortZ || abortY)) {
            phase = 'align';
            settle = 0;
            target = { x: gate.x - 0.30, y: gate.y, z: gate.z };
            targetVel = { x: -0.25, y: 0, z: 0 };
          } else {
