      }

      // 3. Outer loop PD + Wind & Gust compensation ("brake gusts")
      const kDrag = 0.42 / (thrustScale * 15.0);
      const windCompX = fastWindX + 0.48 * gustX;
      const windCompZ = fastWindZ + 0.58 * gustZ;

      const isGateZ = obs.gateIndex < 3;
      const kpX = phase === 'lunge' ? 8.0 : 6.2;
      const kdX = phase === 'lunge' ? 4.6 : 5.2;
      const kpZ = isGateZ ? 12.5 : 6.8;
      const kdZ = isGateZ ? 6.9 : 5.2;

      const ex = clamp(target.x - p.x, -0.75, 0.75);
      const ez = clamp(target.z - p.z, -0.75, 0.75);
      const ey = clamp(target.y - p.y, -0.75, 0.75);

      let ax = kpX * ex + kdX * (targetVel.x - v.x) - windCompX + kDrag * v.x;
      let az = kpZ * ez + kdZ * (targetVel.z - v.z) - windCompZ + kDrag * v.z;
      let ay = 10.0 * ey - 6.0 * v.y + kDrag * v.y;

      ax = clamp(ax, -6.5, 6.5);
      az = clamp(az, -6.5, 6.5);
      ay = clamp(ay, -5.0, 6.5);

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
