      const azBody = sy * ax + cy * az;
      const totalAccY = Math.max(2.5, 9.81 + ay);

      let desPitch = clamp(Math.atan2(axBody, totalAccY), -0.48, 0.48);
      let desRoll = clamp(-Math.atan2(azBody, totalAccY), -0.48, 0.48);

